HERE = pathlib.Path(__file__).resolve().parent
src, dst = sys.argv[1], sys.argv[2]
live = pathlib.Path(src).read_text(encoding='utf-8')
s = live
LINK = '<a href="http://pravo.gov.ru/proxy/ips/?docbody=&amp;nd=602107773&amp;rdk=0" target="_blank" rel="noopener noreferrer">'
