 ('target="_blank" rel="noopener noreferrer">ФЗ №&nbsp;194-ФЗ</a>)', 'target="_blank" rel="noopener noreferrer">Федеральный закон от 29.05.2023 №&nbsp;194-ФЗ</a>)'),
 ('СГР RU.77.99.88.002.Е.002918.07.22, расход 15 г', 'СГР RU.77.99.88.002.Е.XXXXXX.XX.XX, расход 15&nbsp;г'),
